internal object DuaThDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("การเห็นผลครั้งแรก", "โอ้อัลลอฮ์ โปรดอวยพรพวกเราด้วยผลไม้ของเรา อวยพรพวกเราในเมืองของเรา และอวยพรพวกเราด้วยซออฺและโคลนของเรา (มาตรการ)", "เมื่อได้เห็นผลไม้แรกของฤดูกาล", "ดุอาอฺขอพรในเรื่องเสบียงและในเมืองของตน"),
        "dua_good_news" to DuaText("เมื่อมีข่าวน่ายินดี", "การสรรเสริญทั้งมวลเป็นของอัลลอฮ์ ผู้ทรงโปรดปรานความดีของพระองค์", "เมื่อได้รับข่าวดี (และทำการสุญูดแห่งความกตัญญู)", "พระศาสดา ﷺ กล่าวสิ่งนี้เมื่อเห็นสิ่งที่เขาชอบ"),
        "dua_looking_mirror" to DuaText("มองในกระจก", "โอ้อัลลอฮ์ เช่นเดียวกับที่พระองค์ทรงทำให้รูปลักษณ์ของฉันดี โปรดทำให้บุคลิกของฉันดีด้วย", "เมื่อมองไปในกระจก", "ศาสดา ﷺ ได้ทำ dua นี้ (มันถูกสถาปนาแม้ว่าจะไม่มีการเอ่ยถึงกระจกก็ตาม)"),
        "dua_rabbana_taqabbal" to DuaText("การยอมรับการกระทำ", "ข้าแต่พระเจ้าของเรา โปรดยอมรับสิ่งนี้จากพวกเราเถิด แท้จริงพระองค์คือผู้ทรงได้ยิน ผู้ทรงรอบรู้ และยอมรับการกลับใจของเรา แท้จริงพระองค์คือผู้ทรงรับการสำนึกผิด ผู้ทรงเมตตาเสมอ", "ถามโดยอิบรอฮีมและอิสมาอิล (AS) ขณะสร้างกะบะฮ์", "ดุอาให้ได้รับหลังการทำความดีทุกครั้ง"),
        "dua_muawwidhat" to DuaText("ทั้งสามกุล (มุอวิฏัต)", "(ซูเราะห์อัลอิคลาศ) จงกล่าวเถิด พระองค์คืออัลลอฮ์ พระองค์เดียว อัลลอฮ์ผู้ทรงพอเพียง เขาไม่เกิดหรือเกิด และไม่มีใครเทียบเทียมพระองค์ได้\n\n(ซูเราะห์ อัล-ฟาลัค) จงกล่าวเถิด (มุฮัมมัด) ฉันขอความคุ้มครองต่อพระเจ้าแห่งรุ่งสาง จากความชั่วร้ายของสิ่งที่พระองค์ได้ทรงสร้าง จากความชั่วร้ายแห่งความมืดเมื่อมันสงบลง จากความชั่วร้ายของบรรดาผู้ที่ปมเป็นปม และจากความชั่วร้ายของผู้อิจฉาเมื่อเขาอิจฉา\n\n(ซูเราะห์ อัน-นัส) จงกล่าวเถิด (มุฮัมมัด) ฉันขอความคุ้มครองต่อพระเจ้าแห่งมนุษยชาติ กษัตริย์แห่งมนุษยชาติ พระเจ้าแห่งมนุษยชาติ ให้พ้นจากความชั่วร้ายของผู้กระซิบที่ถอยกลับ ผู้กระซิบเข้าไปในหัวใจของมนุษยชาติ จากท่ามกลางญินและมนุษย์", "ซูเราะห์ทั้งสามสามครั้งทุกเช้าและเย็น และก่อนนอนให้เป่าที่มือแล้วเช็ดให้ทั่วร่างกาย", "ท่องไว้สามครั้งเช้าและเย็นก็เพียงพอแล้วกับทุกสิ่ง"),
        "dua_sabr" to DuaText("เพื่อความอดทนและความมั่นคง", "พระเจ้าของเรา โปรดประทานความอดทนแก่เรา โปรดทรงทำให้เท้าของเรามั่นคง และช่วยเราให้พ้นจากกลุ่มผู้ปฏิเสธศรัทธาด้วย", "ในช่วงเวลาแห่งความยากลำบากและการเผชิญหน้า", "ดุอาอ์กองทัพตะลูด"),
        "dua_rabbana_innana_amanna" to DuaText("การให้อภัยและการป้องกันจากอัคคีภัย", "พระเจ้าของเรา เราศรัทธาแล้ว ดังนั้นโปรดอภัยบาปของเราและปกป้องเราจากการลงโทษแห่งไฟด้วย", "ดุอาอัลกุรอาน", "ดุอาที่กล่าวถึงในคุณสมบัติของผู้เกรงกลัวพระเจ้า"),
        "dua_rabbana_hab_lana_rahmah" to DuaText("คำแนะนำในเรื่องของเรา (Ashab al-Kahf)", "พระเจ้าของเรา โปรดประทานความเมตตาจากพระองค์แก่เรา และเตรียมคำแนะนำที่ถูกต้องในเรื่องของเราด้วย", "ดุอาอฺของชาวถ้ำ", "คำแนะนำในการตัดสินใจและสถานการณ์ที่ยากลำบาก"),
        "dua_musa_faqir" to DuaText("Dua ของมูซา (AS) เพื่อการจัดเตรียม", "ข้าแต่พระเจ้า ข้าพระองค์ต้องการสิ่งดี ๆ ที่พระองค์ประทานแก่ข้าพระองค์อย่างแท้จริง", "แสวงหาเสบียงและความดี — ดุอาอ์มูซา (AS) ในมัดยาน", "หลังจากดุอานี้ อัลลอฮ์ทรงประทานบ้าน ที่ทำงาน และภรรยาแก่มูซา (AS)"),
        "dua_ayyub" to DuaText("ดุอาอัยยับ (AS) ในความเจ็บป่วย", "(พระเจ้าของฉัน) อันตรายได้ประสบแก่ฉันแล้ว และพระองค์คือผู้ทรงเมตตาเสมอในหมู่ผู้เมตตา", "ในความเจ็บป่วยและความทุกข์ทรมาน", "อัลลอฮ์ทรงขจัดความทุกข์ทรมานของอัยยูบ (AS)"),
        "dua_husn_khatimah" to DuaText("ตายอย่างมุสลิม (ยูซุฟ อาส)", "ผู้สร้างชั้นฟ้าทั้งหลายและแผ่นดิน พระองค์ทรงเป็นผู้พิทักษ์ของฉันทั้งในโลกนี้และปรโลก ทำให้ฉันตายในฐานะมุสลิมและร่วมกับฉันกับผู้ชอบธรรม", "ดุอาอ์เพื่อการสิ้นสุดที่ดี", "ดุอาของท่านศาสดายูซุฟ (AS)"),
        "dua_shaitan_hamazat" to DuaText("ที่หลบภัยจากเสียงกระซิบของปีศาจ", "ข้าแต่พระเจ้าของฉัน ข้าพระองค์ขอความคุ้มครองต่อพระองค์ให้พ้นจากเสียงกระซิบของพวกมารร้าย และข้าพระองค์ขอความคุ้มครองต่อพระองค์ พระเจ้าของข้าพระองค์ เกรงว่าพวกมันจะมาใกล้ข้าพระองค์", "หลบภัยจากเสียงกระซิบของซาตาน", "ดุอาอ์กุรอานแห่งการแสวงหาที่หลบภัย"),
        "dua_bad_character" to DuaText("ที่หลบภัยจากตัวละครที่ไม่ดี", "โอ้อัลลอฮฺ ฉันขอความคุ้มครองจากพระองค์ให้พ้นจากนิสัยที่ไม่ดี การประพฤติชั่ว และความปรารถนาที่ชั่วร้าย", "ให้พ้นจากอุปนิสัย การกระทำ และกิเลสที่ไม่ดี", "ดุอาขอความคุ้มครองจากท่านศาสดา ﷺ"),
        "dua_zawal_nimah" to DuaText("แคล้วคลาดจากการสูญเสียพระพร", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อพระองค์จากการสูญเสียความโปรดปรานของพระองค์ จากการเปลี่ยนแปลงความเป็นอยู่ที่ดีที่พระองค์ประทาน จากการลงโทษอย่างฉับพลันของพระองค์ และจากความไม่พอใจทั้งหมดของพระองค์", "แคล้วคลาดจากการสูญเสียพรและจากภัยพิบัติอย่างกะทันหัน", "ดุอาของท่านศาสดา ﷺ"),
        "dua_useless_knowledge" to DuaText("หลบภัยจากความรู้อันไม่เป็นประโยชน์", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อพระองค์จากความรู้ที่ไม่เป็นประโยชน์ จากหัวใจที่ไม่เกรงกลัว จากจิตวิญญาณที่ไม่เคยอิ่ม และจากดุอาที่ไม่ได้รับคำตอบ", "จงหลบเลี่ยงจากความรู้ที่ไร้ประโยชน์และหัวใจที่ไม่เกรงกลัวอัลลอฮ์", "ดุอาขอความคุ้มครองจากท่านศาสดา ﷺ"),
        "dua_beneficial_knowledge" to DuaText("ความรู้ที่เป็นประโยชน์และฮาลาลริซคิว", "โอ้อัลลอฮ์ ฉันขอความรู้ที่เป็นประโยชน์ ปัจจัยยังชีพที่บริสุทธิ์ และการกระทำที่ได้รับการยอมรับจากพระองค์", "หลังจากละหมาดฟัจร์.", "ท่านศาสดาหมายเลข ﷺ กล่าวสิ่งนี้หลังสลามฟัจร์"),
        "dua_leprosy_diseases" to DuaText("ที่หลบภัยจากโรคร้ายแรง", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อพระองค์ให้พ้นจากโรคด่างขาว ความบ้าคลั่ง โรคเรื้อน และโรคร้ายต่างๆ", "คุ้มครองจากโรคร้ายแรง", "ซุนนะฮฺ dua เพื่อรักษาสุขภาพ"),
        "dua_fear_people" to DuaText("ความกลัวศัตรูหรือผู้กดขี่", "โอ้อัลลอฮ์ เราได้ให้พระองค์อยู่เบื้องหน้าพวกเขา และขอความคุ้มครองต่อพระองค์ให้พ้นจากความชั่วร้ายของพวกเขา", "เมื่อกลัวอันตรายของคนหรือบุคคล", "พระศาสดา ﷺ กล่าวสิ่งนี้เมื่อเขากลัวผู้คน"),
        "dua_shirk_protection" to DuaText("การคุ้มครองจากชิริกที่ซ่อนอยู่", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองจากพระองค์จากการจงใจเชื่อมโยงสิ่งใดๆ กับพระองค์ และฉันขออภัยโทษต่อสิ่งที่ฉันกระทำโดยไม่รู้ตัว", "เพื่อความปลอดภัยจากการโอ้อวดและชิริกที่ซ่อนอยู่", "ชิริกที่ซ่อนเร้นนั้นปกปิดยิ่งกว่าการคลานของมด"),
        "dua_rain" to DuaText("เมื่อฝนตก", "โอ้อัลลอฮ์ (ทรงประทาน) ฝนอันเป็นประโยชน์", "เมื่อฝนตก.", "ฝนเป็นช่วงที่ดุอาอฺเป็นที่ยอมรับ"),
        "dua_after_rain" to DuaText("หลังฝนตก", "เราได้รับฝนด้วยความโปรดปรานของอัลลอฮ์และความเมตตาของพระองค์", "หลังฝนตก.", "ผู้ที่กล่าวว่านี่คือผู้ศรัทธาในอัลลอฮ."),
        "dua_istisqa" to DuaText("การขอฝน (อิสติสกา)", "โอ้อัลลอฮ์ โปรดประทานฝนแก่เรา (สามครั้ง)", "เมื่อฝนไม่ตก.", "พระศาสดาหมายเลข ﷺ ทรงดุอาอ์นี้ในการเทศน์วันศุกร์ และฝนตก"),
        "dua_heavy_rain" to DuaText("ฝนตกหนักมาก", "โอ้อัลลอฮ์ (ให้มันตก) รอบตัวเรา มิใช่อยู่บนเรา", "เมื่อมีฝนตกมากเกินไป", "เมฆเคลื่อนตัวออกไปตามดุอาของศาสดาพยากรณ์ ﷺ"),
        "dua_wind" to DuaText("เมื่อลมพัด", "โอ้อัลลอฮ์ ฉันขอความคุ้มครองจากพระองค์ ความดีในตัวมัน และความดีของสิ่งที่ถูกส่งมา และฉันขอความคุ้มครองจากพระองค์ให้พ้นจากความชั่วร้ายของมัน ความชั่วร้ายในตัวมัน และความชั่วร้ายของสิ่งที่ถูกส่งไปด้วย", "เมื่อมีลมแรงหรือพายุพัดมา", "พระศาสดา ﷺ ทรงทำดุอานี้ระหว่างเกิดพายุ"),
        "dua_thunder" to DuaText("ได้ยินเสียงฟ้าร้อง", "มหาบริสุทธิ์แห่งพระองค์ผู้ทรงฟ้าร้องสรรเสริญด้วยการสรรเสริญพระองค์ และเหล่าทูตสวรรค์ที่เกรงกลัวพระองค์", "เมื่อได้ยินเสียงฟ้าร้อง — การปฏิบัติของอับดุลลอฮฺ บิน อัซ-ซูบัยร์ (RA)", "นำมาจากซูเราะห์อัรเราะด์ (13:13)"),
        "dua_new_moon" to DuaText("มองเห็นพระจันทร์ใหม่", "โอ้อัลลอฮ์ โปรดให้ดวงจันทร์นี้ขึ้นเหนือเราด้วยความโปรดปราน ความศรัทธา ความปลอดภัย และศาสนาอิสลาม (โอ้ ดวงจันทร์) พระเจ้าของฉันและพระเจ้าของพวกท่านคืออัลลอฮฺ", "เมื่อได้เห็นพระจันทร์ใหม่", "ซุนนะฮฺ dua สำหรับทุกเดือนใหม่"),
        "dua_janaza_adult" to DuaText("คำอธิษฐาน Janaza (ผู้ใหญ่)", "โอ้อัลลอฮ์ โปรดอภัยโทษแก่เราทั้งคนเป็นและคนตาย ทั้งในปัจจุบันและที่หายไป ทั้งเด็กและผู้ใหญ่ของเรา ชายและหญิงของเรา โอ้อัลลอฮ์ ผู้ใดในหมู่พวกเราที่พระองค์ทรงมีชีวิตอยู่ ก็ทรงให้เขามีชีวิตอยู่ตามหลักอิสลาม และผู้ใดในหมู่พวกเราที่พระองค์ทรงให้ตาย ก็ให้เขาตายด้วยศรัทธา", "หลังจากตักบีรครั้งที่ 3 ของพิธีสวดอภิธรรม", "ซุนนะฮฺ dua สำหรับผู้ใหญ่ที่เสียชีวิต"),
        "dua_janaza_child" to DuaText("คำอธิษฐาน Janaza (เด็ก)", "โอ้อัลลอฮ์ โปรดทำให้เขาเป็นผู้เบิกทาง (และเป็นเจ้าภาพ) แก่เรา ทำให้เขาได้รับรางวัลและเป็นสมบัติสำหรับเรา และทำให้เขาเป็นผู้วิงวอนแทนเราซึ่งการวิงวอนของเขาได้รับการยอมรับ", "ในการละหมาดงานศพของเด็ก (สำหรับผู้หญิงพูดว่า 'อิจอัลฮา')", "ดุอาซุนนะฮฺที่ฮานาฟิสปฏิบัติ"),
        "dua_mayyit_awf" to DuaText("Dua รายละเอียดสำหรับผู้ตาย", "โอ้อัลลอฮ์ โปรดอภัยโทษให้เขา เมตตาเขา ให้ความอยู่ดีมีสุขแก่เขา และให้อภัยเขาด้วย จงให้การต้อนรับเขาอย่างมีเกียรติ และหลุมศพของเขากว้างขวาง ล้างเขาด้วยน้ำ หิมะ และลูกเห็บ และชำระเขาให้พ้นจากบาป ดังผ้าขาวที่ปราศจากสิ่งสกปรก", "ในการสวดอภิธรรมศพหรือเพื่อผู้วายชนม์", "เอาฟ์ อิบนุ มาลิก (RA) ปรารถนาว่าเขาคือผู้เสียชีวิตคนนั้น"),
        "dua_visiting_graves" to DuaText("เยี่ยมชมหลุมศพ", "ขอความสันติสุขจงมีแด่ท่าน โอ้ผู้ศรัทธาและชาวมุสลิมในบ้านเหล่านี้ เราก็เช่นกันหากอัลลอฮ์ทรงประสงค์ก็จะร่วมกับพวกท่าน ฉันขออัลลอฮ์เพื่อความอยู่ดีมีสุขสำหรับเราและสำหรับคุณ", "เมื่อเข้าไปในสุสาน", "การไปเยี่ยมหลุมศพทำให้นึกถึงความตายและปรโลก"),
        "dua_closing_eyes" to DuaText("เมื่อหลับตาของผู้ตาย", "โอ้อัลลอฮ์ โปรดอภัยโทษ (ชื่อ) ยกระดับตำแหน่งของเขาในหมู่ผู้แนะนำ และเป็นผู้สืบทอดของเขาในหมู่ผู้ที่เขาทิ้งไว้ข้างหลัง โปรดยกโทษให้เราและเขาด้วย ข้าแต่พระเจ้าแห่งสากลโลก ให้หลุมศพของเขากว้างขวางและเติมแสงสว่างให้เต็ม", "เมื่อหลับตาของผู้ตาย(กล่าวถึงชื่อของเขา)", "พระศาสดาหมายเลข ﷺ ได้ตั้งดุอานี้ให้กับอบูสะลามะห์หมายเลข (RA)"),
        "dua_condolence" to DuaText("ขอแสดงความเสียใจ (ตะอฺซียะฮ์)", "แท้จริงสิ่งที่พระองค์ทรงรับนั้นเป็นกรรมสิทธิ์ของอัลลอฮ์ และสิ่งที่พระองค์ประทานให้เป็นของพระองค์ และทุกสิ่ง ณ ที่พระองค์นั้นมีกำหนดเวลา ดังนั้นจงอดทนและหวังผลบุญ", "แสดงความเสียใจกับครอบครัวหลังการเสียชีวิต", "ศาสดาพยากรณ์ ﷺ ส่งข้อความนี้ถึงลูกสาวของเขา"),
        "dua_placing_in_grave" to DuaText("การนำผู้ตายไปฝังในหลุมศพ", "ด้วยพระนามของอัลลอฮ์ และบนหนทางของท่านศาสนทูตของอัลลอฮ์ ﷺ", "เมื่อนำร่างผู้เสียชีวิตลงหลุมศพแล้ว", "ซุนนะฮฺ dua ของการฝังศพ"),
        "dua_sneezing" to DuaText("จาม", "การสรรเสริญทั้งหมดเป็นของอัลลอฮ์ - ขออัลลอฮ์ทรงเมตตาท่าน. — ขออัลลอฮ์ทรงนำทางคุณและจัดการกิจการของคุณให้ถูกต้อง", "เมื่อจาม; ผู้ฟังพูดว่า 'Yarhamukallah' จากนั้นผู้ที่จามก็ตอบกลับ", "มันเป็นสิทธิประการหนึ่งของมุสลิมเหนือมุสลิมอีกคนหนึ่ง"),
        "dua_toilet_enter" to DuaText("เข้าห้องน้ำ", "ในนามของอัลลอฮ. โอ้อัลลอฮ์ ฉันขอความคุ้มครองต่อพระองค์จากญินชั่วชายและหญิง", "ก่อนจะก้าวเข้าห้องน้ำด้วยเท้าซ้าย", "บิสมิลลาห์กลายเป็นม่านกั้นระหว่างญินกับบุคคล"),
        "dua_toilet_exit" to DuaText("ออกจากห้องน้ำ", "(โอ้อัลลอฮ์) ฉันขออภัยโทษจากพระองค์", "เมื่อก้าวออกจากห้องน้ำด้วยเท้าขวา", "พระศาสดา ﷺ กล่าวสิ่งนี้เมื่อออกจากห้องน้ำ"),
        "dua_thanking" to DuaText("ขอบคุณใครบางคน", "ขออัลลอฮ์ตอบแทนคุณด้วยความดี", "เมื่อมีคนช่วยเหลือคุณ", "ใครก็ตามที่พูดสิ่งนี้ก็แสดงความขอบคุณอย่างเต็มที่"),
        "dua_love_for_allah" to DuaText("เมื่อมีคนพูดว่า 'ฉันรักคุณเพื่ออัลลอฮ์'", "ขอให้พระองค์ (อัลลอฮ์) ทรงรักฉัน ทรงรักคุณ", "เมื่อมีคนพูดว่า 'ฉันรักคุณเพื่ออัลลอฮ์'", "ซุนนะฮฺตอบความรักเพื่อประโยชน์ของอัลลอฮ์"),
        "dua_seeing_muslim_smile" to DuaText("การทักทาย (สลาม)", "สันติภาพจงมีแด่คุณและความเมตตาของอัลลอฮ์และพรของพระองค์", "เมื่อพบกับมุสลิม", "การกล่าวสลามให้ครบถ้วนจะได้ความดีสามสิบประการ"),
        "dua_dressing" to DuaText("การแต่งตัว", "การสรรเสริญทั้งหมดเป็นของอัลลอฮ์ผู้ทรงสวมสิ่งนี้ให้ฉันและทรงจัดเตรียมมันให้ฉันโดยปราศจากอำนาจหรืออำนาจใด ๆ ในส่วนของฉัน", "เมื่อจะแต่งตัว.", "ข่าวดีแห่งการอภัยบาปในอดีต"),
    )
}
